import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.*;
import ghidra.program.model.listing.*;
public class BspExtendReviewedBody extends GhidraScript {
 public void run() throws Exception {
  if (!currentProgram.getDomainFile().getPathname().equals("/battlestationspacific.exe"))
   throw new IllegalStateException("Wrong BSP program");
  Address start=toAddr(0x451020L), end=toAddr(0x4512d3L);
  Function f=currentProgram.getFunctionManager().getFunctionAt(start);
  if(f==null) throw new IllegalStateException("Missing existing function");
  Address cursor=start;
  while(cursor.compareTo(end)<0) {
   Instruction i=currentProgram.getListing().getInstructionAt(cursor);
   if(i==null) throw new IllegalStateException("Undecoded instruction at "+cursor);
   Function other=currentProgram.getFunctionManager().getFunctionContaining(cursor);
   if(other!=null && other!=f) throw new IllegalStateException("Other function at "+cursor);
   cursor=cursor.add(i.getLength());
  }
  if(!cursor.equals(end)) throw new IllegalStateException("End is not an instruction boundary");
  println("BSP_BODY_BEFORE: "+f.getBody().toString());
  AddressSet extended=new AddressSet(f.getBody());
  extended.addRange(start,end.subtract(1));
  int transaction=currentProgram.startTransaction("Extend reviewed BSP function tail");
  boolean commit=false;
  try { f.setBody(extended); commit=true; }
  finally { currentProgram.endTransaction(transaction,commit); }
  println("BSP_BODY_AFTER: "+f.getBody().toString());
 }
}
